CREATE TABLE IF NOT EXISTS `trade-analytics-508604.trade_analytics_published.legacy_world_lineage_backup` AS
SELECT w.*,CURRENT_TIMESTAMP() backed_up_at FROM `trade-analytics-508604.trade_raw.un_comtrade_world_total` w
WHERE period_start_date=DATE '2023-01-01';

BEGIN TRANSACTION;
ASSERT (SELECT COUNT(*)=1 FROM `trade-analytics-508604.trade_raw.un_comtrade_world_total` WHERE period_start_date=DATE '2023-01-01') AS 'world_count';
ASSERT (SELECT TO_JSON_STRING(w) FROM `trade-analytics-508604.trade_raw.un_comtrade_world_total` w WHERE period_start_date=DATE '2023-01-01')=@before AS 'raw_changed_since_read';
UPDATE `trade-analytics-508604.trade_raw.un_comtrade_world_total` SET checksum=@checksum,ingested_at=TIMESTAMP(@ingested)
WHERE period_start_date=DATE '2023-01-01' AND partner_code='0' AND cmd_code='8542' AND hs_version='H6' AND revision=1;
COMMIT TRANSACTION;
